    outFlowMeter = s.fields.find(f => f.name === 'Out Flow Meter Reading')?.values ?? [];
  }
});

// Format dates
const formattedDates = timeData.map(d => {
  const date = new Date(d);
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + 1;
  const day = date.getUTCDate();
  return `${month}/${day}/${year}`;
});

return {
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'cross',
    },
    formatter: function (params) {
      let tooltipText = `${params[0].axisValueLabel}<br/>`;
      params.forEach((item) => {
        let value = item.data === '-' ? '-' : `${item.data} m^3/day`;
        tooltipText += `${item.marker} ${item.seriesName}: ${value}<br/>`;
      });
      return tooltipText;
