      formatter: function (val) {
        const date = new Date(val);
        const month = date.getMonth() + 1;
        const day = date.getDate();
        return `${month}/${day}`;
      }
    }
  },
  yAxis: {
    type: 'value',
    axisLabel: {
      formatter: function (val) {
        return `${val} m^3/day`;
      },
    },
  },
  series: [
    {
      name: 'Flow Meter(In)',
      type: 'line',
      data: inFlowMeter.map(value => (value == null || value <= 0 ? "-" : value))
    },
    {
      name: 'Flow Meter(Out)',
      type: 'line',
      data: outFlowMeter.map(value => (value == null || value <= 0 ? "-" : value))
